{
  "name": "@rvboris/opencode-mempalace",
  "version": "2.0.1",
  "description": "OpenCode plugin for hidden MemPalace retrieval and autosave via a local Python adapter.",
  "type": "module",
  "main": "dist/plugin/index.js",
  "types": "dist/plugin/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/plugin/index.js",
      "types": "./dist/plugin/index.d.ts"
    },
    "./server": {
      "import": "./dist/plugin/index.js",
      "types": "./dist/plugin/index.d.ts"
    },
    "./tui": {
      "import": "./dist/plugin/tui/index.js",
      "types": "./dist/plugin/tui/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md",
    "README.ru.md",
    "LICENSE",
    "example-opencode.json"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mempalace",
    "memory"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/rvboris/opencode-mempalace.git"
  },
  "dependencies": {
    "@opencode/client": "2.0.22",
    "@opencode/theme": "2.0.22"
  },
  "peerDependencies": {
    "@opencode/plugin": "2.0.22",
    "@opentui/core": "^0.5.14",
    "@opentui/solid": "^0.5.14",
    "solid-js": "^1.9.12"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.4.12",
    "@opencode/plugin": "2.0.22",
    "@opentui/core": "^0.5.14",
    "@opentui/solid": "^0.5.14",
    "solid-js": "^1.9.12",
    "@types/bun": "^1.3.0",
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "lint": "biome lint plugin tests scripts package.json tsconfig.json example-opencode.json biome.json",
    "lint:ci": "biome lint plugin tests scripts package.json tsconfig.json example-opencode.json biome.json",
    "prepublishOnly": "npm run build",
    "test": "bun run build && bun test --parallel ./tests/*.test.ts && bun test --conditions=browser --preload @opentui/solid/preload tests/v2-hud.test.tsx && bun test --conditions=browser tests/v2-hud-built.test.tsx",
    "test:coverage": "bun run build && bun test --parallel ./tests/*.test.ts --coverage --coverage-reporter=text --coverage-reporter=lcov && bun test --conditions=browser --preload @opentui/solid/preload tests/v2-hud.test.tsx && bun test --conditions=browser tests/v2-hud-built.test.tsx",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "publishConfig": {
    "access": "public"
  }
}
